import React, { useState } from 'react';

// Create the App component here
const App = () => {
  // Initialize state for controlled input here
  const [controlledValue, setControlledValue] = useState('');

  // Create the change handler function here
  const handleChange = (e) => {
    setControlledValue(e.target.value);
  };

  // Create a ref for uncontrolled input here
  const uncontrolledRef = React.useRef(null);

  // Create a handler to read uncontrolled input value here
  const handleReadUncontrolled = () => {
    alert('Uncontrolled value: ' + uncontrolledRef.current.value);
  };

  // Create a reset handler for controlled input here
  const handleResetControlled = () => {
    setControlledValue('');
  };

  return (
    <div>
      {/* Add a controlled input field here */}
      <input 
        type="text" 
        value={controlledValue} 
        onChange={handleChange} 
        placeholder="Type here (controlled)"
      />
      <p>Controlled value: {controlledValue}</p>

      {/* Add an uncontrolled input field here */}
      <input 
        type="text" 
        ref={uncontrolledRef} 
        placeholder="Type here (uncontrolled)"
      />
      <button onClick={handleReadUncontrolled}>Read Uncontrolled Value</button>

      {/* Add reset button for controlled input here */}

    </div>
  );
};

export default App;
